<script setup lang="ts">
import {ref,onMounted,onUnmounted,watch,nextTick} from 'vue';
const props=defineProps<{api:(path:string,method?:string,body?:any)=>Promise<any>,can:(permission:string)=>boolean,initialCode?:string}>();
const emit=defineEmits<{reader:[id:number]}>();
const reportOpen=ref(false);
const number=(n:number)=>new Intl.NumberFormat('ru-RU').format(n);
function day(v:string){return v.split('-').reverse().join('.');}
async function showReport(){reportOpen.value=!reportOpen.value;await nextTick();if(reportOpen.value)document.getElementById('visits-report')?.scrollIntoView({block:'start'});}
async function turnPage(delta:number){if(busy.value)return;busy.value=true;error.value='';const previous=offset.value;offset.value=Math.max(0,previous+delta);try{await refresh();await nextTick();document.getElementById('visits-journal')?.scrollIntoView({block:'start'});}catch(e){offset.value=previous;error.value=String(e);}finally{busy.value=false;}}
const code=ref(props.initialCode||''),branch=ref<number|null>(Number(localStorage.getItem('reader-visit-branch'))||null),notes=ref(''),branches=ref<any[]>([]),found=ref<any>(null),result=ref<any>(null),journal=ref<any>({items:[],total:0}),stats=ref<any>(null),offset=ref(0),busy=ref(false),error=ref(''),input=ref<HTMLInputElement|null>(null);let generation=0,timer:ReturnType<typeof setTimeout>;
function dateTime(v:string){return new Date(v.endsWith('Z')||/[+-]\d\d:\d\d$/.test(v)?v:v+'Z').toLocaleString('ru-RU',{timeZone:'Asia/Almaty'});}
watch(branch,v=>localStorage.setItem('reader-visit-branch',String(v||'')));
watch(code,()=>{const token=++generation;found.value=null;error.value='';clearTimeout(timer);if(!code.value.trim())return;timer=setTimeout(async()=>{try{const r=await props.api('/visits/lookup?code='+encodeURIComponent(code.value));if(token===generation)found.value=r;}catch(e){if(token===generation)error.value=String(e);}},250);},{immediate:true});
async function refresh(){if(props.can('visits.view')){[journal.value,stats.value]=await Promise.all([props.api('/visits?offset='+offset.value),props.api('/visits/analytics')]);}}
async function scan(){if(busy.value)return;busy.value=true;error.value='';clearTimeout(timer);generation++;try{result.value=await props.api('/visits','POST',{code:code.value,branch_id:branch.value,notes:notes.value,source:'desk'});code.value='';notes.value='';found.value=null;offset.value=0;await refresh();}catch(e){error.value=String(e);}finally{busy.value=false;await nextTick();input.value?.focus();}}
onUnmounted(()=>{generation++;clearTimeout(timer);});
onMounted(async()=>{try{branches.value=(await props.api('/reader-branches')).filter((b:any)=>b.active);if(!branches.value.some(b=>b.id===branch.value))branch.value=branches.value[0]?.id||null;await refresh();input.value?.focus();}catch(e){error.value=String(e);}});
</script>
<template>
<section class="visits-page" :aria-busy="busy">
<div class="page-heading"><div><h1>Отметка посещений</h1><p>Сканирование читательского билета на входе. Визит фиксируется отдельно от книговыдачи — даже если читатель ничего не брал.</p></div><button v-if="can('visits.view')" :aria-expanded="reportOpen" @click="showReport">▥ Отчёт по посещаемости</button></div>
<p v-if="error" class="error visit-alert" role="alert">{{error}}</p>
<div v-if="stats" class="visit-metrics">
<article class="card"><span class="visit-metric-icon" aria-hidden="true">▣</span><div><strong>{{number(stats.today.visits)}}</strong><span>Посещений сегодня</span></div></article>
<article class="card"><span class="visit-metric-icon" aria-hidden="true">♙</span><div><strong>{{number(stats.today.unique)}}</strong><span>Читателей сегодня</span></div></article>
<article class="card"><span class="visit-metric-icon" aria-hidden="true">▦</span><div><strong>{{number(stats.visits)}}</strong><span>Посещений за 7 дней</span></div></article>
</div>
<form v-if="can('visits.record')" class="card visit-scan-card" @submit.prevent="scan">
<div class="visit-scan-row"><label class="visit-code-label">Штрихкод или номер билета<input ref="input" aria-label="Штрихкод или номер билета" v-model="code" maxlength="100" class="scan-input" autocomplete="off" placeholder="RDR00000001" required :disabled="busy" aria-describedby="visit-scan-help"><small id="visit-scan-help">Отсканируйте штрихкод с читательского билета или введите его вручную. Номер билета тоже подходит.</small></label><label>Пункт обслуживания<select v-model="branch" required :disabled="busy"><option :value="null">Выберите пункт</option><option v-for="b in branches" :key="b.id" :value="b.id">{{b.name}}</option></select></label><button class="primary" :disabled="busy||!branch||!code.trim()">{{busy?'Регистрация…':'✓ Отметить визит'}}</button></div>
<div v-if="found" class="visit-reader-preview"><span class="visit-reader-avatar">{{found.full_name?.charAt(0)}}</span><div><strong>{{found.full_name}}</strong><small>{{found.ticket_number}} · {{({active:'Активен',blocked:'Заблокирован',suspended:'Приостановлен'} as any)[found.status]||found.status}}</small><p v-if="found.block_reason">{{found.block_reason}}</p></div></div>
<details class="visit-note"><summary>Добавить примечание</summary><label>Примечание<input v-model="notes" maxlength="1000" :disabled="busy"></label></details>
<p class="visit-scan-hint">Повторное сканирование одного билета в течение 10 минут считается тем же визитом — повторные отметки не завышают статистику.</p><p v-if="!branches.length" class="visit-alert error">Сначала добавьте пункт обслуживания в разделе «Читатели».</p>
</form>
<div v-if="result" class="visit-alert success" role="status"><strong>{{result.duplicate?'Повторный скан: посещение уже учтено':'✓ Посещение зарегистрировано'}}</strong><p>{{result.full_name}} · {{dateTime(result.scanned_at)}}</p></div>
<section v-if="can('visits.view')" id="visits-journal" class="card visit-journal"><div class="section-heading"><h2>Последние отметки</h2><span>{{number(journal.total)}} посещений</span></div><div class="visit-table-scroll"><table><thead><tr><th>Читатель</th><th>Время</th><th>Пункт обслуживания</th><th>Точка отметки</th><th>Отметил</th></tr></thead><tbody><tr v-for="v in journal.items" :key="v.id"><td><button class="visit-reader-link" v-if="can('readers.registry.view')" @click="emit('reader',v.reader_id)">{{v.full_name}}</button><strong v-else>{{v.full_name}}</strong><small class="mono">{{v.ticket_number}}</small></td><td>{{dateTime(v.scanned_at)}}</td><td>{{v.branch}}</td><td>{{({desk:'Рабочее место',kiosk:'Киоск',turnstile:'Турникет'} as any)[v.source]||v.source}}<small v-if="v.notes">{{v.notes}}</small></td><td>{{v.actor}}</td></tr><tr v-if="!journal.items.length"><td colspan="5" class="visit-empty"><strong>Посещений пока нет</strong><p>Здесь появятся отметки после сканирования читательских билетов.</p></td></tr></tbody></table></div><div class="table-footer"><span>{{journal.total?offset+1:0}}–{{Math.min(offset+50,journal.total)}} из {{number(journal.total)}}</span><div><button :disabled="busy||offset===0" @click="turnPage(-50)">← Назад</button><button :disabled="busy||offset+50>=journal.total" @click="turnPage(50)">Далее →</button></div></div></section>
<section v-if="reportOpen&&stats" id="visits-report" class="card visit-report"><div class="section-heading"><div><h2>Отчёт по посещаемости</h2><p>Последние 7 дней · время Алматы</p></div><button @click="reportOpen=false">Закрыть отчёт</button></div><div class="visit-report-grid"><div><h3>Посещения по дням</h3><div class="visit-days"><div v-for="d in stats.days" :key="d.date"><span>{{day(d.date)}}</span><div class="visit-bar-track"><div :style="{width:(d.visits/Math.max(1,...stats.days.map((x:any)=>x.visits))*100)+'%'}"></div></div><strong>{{number(d.visits)}}</strong><small>{{d.unique}} читателей</small></div></div></div><div><h3>По пунктам обслуживания</h3><p v-if="!stats.branches.length" class="muted">За этот период посещений нет.</p><div v-for="b in stats.branches" :key="b.name" class="visit-branch-total"><span>{{b.name}}</span><strong>{{number(b.visits)}}</strong></div></div></div></section>
</section>
</template>
<style scoped>
.visits-page .page-heading>div{max-width:1000px}.visits-page .page-heading>button{flex-shrink:0}.visit-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;margin:28px 0}.visit-metrics article{display:flex;align-items:center;gap:20px;padding:28px;min-height:120px}.visit-metric-icon{display:grid;place-items:center;background:#eff6f8;color:#007e80;border-radius:18px;width:56px;height:56px;font-size:27px;flex-shrink:0}.visit-metrics strong{display:block;color:#101e31;font-size:30px;margin-bottom:10px}.visit-metrics article div>span{color:#7588a2;font-size:12px;text-transform:uppercase;letter-spacing:.4px}.visit-scan-card{padding:26px;margin:28px 0}.visit-scan-row{display:grid;grid-template-columns:minmax(0,2fr) minmax(180px,1fr) minmax(180px,1fr);gap:20px;align-items:start}.visit-scan-row label{font-weight:600;font-size:14px}.visit-scan-row small{font-size:12px;line-height:1.6;font-weight:400;color:#7588a2}.scan-input{font-family:ui-monospace,monospace;font-size:19px}.visit-scan-row input,.visit-scan-row select{height:48px}.visit-scan-row>.primary{margin-top:27px;min-height:48px;font-weight:650}.visit-note{margin-top:18px;font-size:12px;color:#60758d}.visit-note label{margin-top:12px}.visit-scan-hint{font-size:12px;margin-top:18px;color:#7588a2}.visit-alert{padding:18px 22px;border-radius:12px;margin:18px 0}.visit-alert p{color:inherit}.visit-reader-preview{display:flex;gap:14px;align-items:center;margin-top:18px;padding:16px;background:#f2f8fa;border:1px solid #dce9ec;border-radius:12px}.visit-reader-avatar{display:grid;place-items:center;width:40px;height:44px;background:#052744;color:white;border-radius:10px}.visit-reader-preview small{display:block;margin-top:4px;color:#6e8197}.visit-journal{margin:28px 0;overflow:hidden;scroll-margin-top:24px}.visit-journal .section-heading{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:24px}.visit-journal .section-heading h2{margin:0}.visit-journal .section-heading>span{color:#7588a2;font-size:12px}.visit-table-scroll{overflow:auto}.visit-journal table{min-width:800px}.visit-journal td{vertical-align:middle}.visit-journal small{display:block;color:#7588a2;margin-top:6px}.visit-journal .visit-reader-link{background:none;border:0;box-shadow:none;padding:0;min-height:0;text-align:left;font-weight:650;color:#172438;line-height:1.5}.visit-empty{text-align:center;padding:48px 20px!important}.visit-report{scroll-margin-top:24px;overflow:hidden}.visit-report .section-heading{display:flex;align-items:center;justify-content:space-between;gap:15px}.visit-report-grid{display:grid;grid-template-columns:1.5fr 1fr;gap:40px;padding:0 26px 26px}.visit-days>div{display:grid;grid-template-columns:85px minmax(30px,1fr) 32px 85px;align-items:center;gap:10px;margin:18px 0;font-size:12px;color:#64758b}.visit-days strong{color:#17354c;text-align:right}.visit-days small{text-align:right}.visit-bar-track{height:10px;background:#edf3f6;border-radius:8px;overflow:hidden}.visit-bar-track>div{height:100%;background:#198e91;border-radius:8px}.visit-branch-total{display:flex;justify-content:space-between;gap:16px;padding:16px 0;border-bottom:1px solid #e5ebf2;font-size:14px}
@media(max-width:1100px){.visit-scan-row{grid-template-columns:minmax(0,2fr) minmax(160px,1fr)}.visit-scan-row>.primary{margin-top:0;grid-column:1/-1;justify-self:end}.visit-metrics article{padding:20px;gap:12px}.visit-metric-icon{width:42px;height:46px}.visit-report-grid{grid-template-columns:1fr;gap:10px}}
@media(max-width:650px){.visit-metrics{grid-template-columns:1fr;gap:12px}.visit-metrics article{min-height:90px}.visit-metrics strong{font-size:26px;margin-bottom:4px}.visit-scan-row{grid-template-columns:1fr}.visit-scan-card{padding:20px}.visit-scan-row>.primary{justify-self:stretch}.visit-journal .section-heading{flex-wrap:wrap}.visit-days>div{grid-template-columns:75px 1fr 25px}.visit-days small{grid-column:2/-1}.visit-report .section-heading{flex-wrap:wrap}}
</style>
